// OPENING TEMPLATES — authored by Conductor (Phase 3 report), installed verbatim.
// Rail only selects and fills. If a required placeholder is empty, fall back to
// the cold template — never speak a broken sentence.
const T = {
  cold: "Welcome to AI Voice Agency, this is AVA — I help businesses stop losing calls and leads to voicemail. What kind of business do you run?",
  known: "Hey {{caller_first_name}}, thanks for calling AI Voice Agency back — this is AVA.",
  appointment: "Hey {{caller_first_name}} — I see you're on the calendar for {{appointment_time_caller_local}}. Calling about that one?",
  web_activity: "Hi, this is AVA with AI Voice Agency — looks like you were just checking us out online. What can I help with?"
};
const ex = $('Extract').first().json;
const c = ($('Pick Contact').first().json.contact) || {};
const resp = $json || {};
const events = Array.isArray(resp.events) ? resp.events : [];
const now = DateTime.now();
const CT = 'America/Chicago';
const parseWhen = s => {
  if (!s) return DateTime.invalid('empty');
  let dt = DateTime.fromISO(s, { setZone: true });
  if (dt.isValid) return dt;
  dt = DateTime.fromFormat(s, 'yyyy-MM-dd HH:mm:ss', { zone: CT });
  if (dt.isValid) return dt;
  return DateTime.fromFormat(s, 'yyyy-MM-dd HH:mm', { zone: CT });
};
const zoneLabel = z => ({'America/New_York':'Eastern Time','America/Chicago':'Central Time','America/Denver':'Mountain Time','America/Los_Angeles':'Pacific Time','America/Phoenix':'Arizona Time'})[z] || (z || '');
const good = ['confirmed','new','booked','showed'];
const upcoming = events
  .filter(e => e && e.startTime && e.deleted !== true)
  .map(e => ({ e, dt: parseWhen(e.startTime) }))
  .filter(x => x.dt.isValid && x.dt > now && (!x.e.appointmentStatus || good.indexOf((x.e.appointmentStatus + '').toLowerCase()) !== -1))
  .sort((a, b) => a.dt.toMillis() - b.dt.toMillis());
const fmt = d => d.toFormat("cccc, LLL d 'at' h:mm a");
const next = upcoming[0] || null;
const tz = c.timezone || '';
const addedRecent = (() => { const t = DateTime.fromISO(c.dateUpdated || c.dateAdded || ''); return t.isValid && now.diff(t, 'minutes').minutes <= 15; })();
const first = (c.firstNameRaw || c.firstName || '').toString();
const apptLocal = (next && tz) ? (fmt(next.dt.setZone(tz)) + ' ' + zoneLabel(tz)) : '';
const apptCT = next ? (fmt(next.dt.setZone(CT)) + ' Central Time') : '';
const opening_mode = next ? 'appointment' : (addedRecent ? 'web_activity' : 'known');
const fill = (tpl, map) => {
  let out = tpl;
  for (const k of Object.keys(map)) out = out.split('{{' + k + '}}').join(map[k]);
  return out;
};
const apptTime = apptLocal || apptCT;
let opening_line;
if (opening_mode === 'appointment' && first && apptTime) {
  opening_line = fill(T.appointment, { caller_first_name: first, appointment_time_caller_local: apptTime });
} else if (opening_mode === 'known' && first) {
  opening_line = fill(T.known, { caller_first_name: first });
} else if (opening_mode === 'web_activity') {
  opening_line = T.web_activity;
} else {
  opening_line = T.cold;
}
const vars = {
  caller_known: 'true',
  caller_first_name: first,
  caller_cell_e164: (ex.from_number || '').toString(),
  caller_timezone_label: zoneLabel(tz),
  recent_web_activity: addedRecent ? 'true' : 'false',
  has_upcoming_appointment: next ? 'true' : 'false',
  appointment_time_ct: apptCT,
  appointment_time_caller_local: apptLocal,
  appointment_count_upcoming: String(upcoming.length),
  opening_mode: opening_mode,
  opening_line: opening_line
};
return [{ json: { vars } }];
